entries[370676] = { ["name"] = "Nährender Alchemistenstein", ["text"] = "Wirken in 2 sek. 3\nReagenzien:\nLeuchtende Titanenkugel , Phiole der mäßigen Vielseitigkeit (6), Phiole des elementaren Chaos (6), Urzeitliche Konvergenz (4), Funke (#247)\nOptionale Reagenzien:\nAlchemistischer Katalysator (#94) , Glorreiche Einsicht (#93) , Mit Energie erfüllen (#126)\nVerkäufer:\nDothenos\nZone:\nValdrakken\nKosten:\n400\n\nVerkäufer:\nUnatos\nZone:\nValdrakken\nKosten:\n400\n\nNährender Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)Schmuck\n+ 342 Vielseitigkeit\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert 10 Sek. lang um 687 und die Dauer Eurer aktiven Phiolen um 60 Sek. zu erhöhen.\n60\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[370677] = { ["name"] = "Lebhafter Alchemistenstein", ["text"] = "Wirken in 2 sek. 3\nReagenzien:\nLeuchtende Titanenkugel , Trank des gefrorenen Fokus (12), Elementartrank der Macht (12), Omnium Draconis (15), Funke (#247)\nOptionale Reagenzien:\nMit Energie erfüllen (#126) , Alchemistischer Katalysator (#91) , Glorreiche Einsicht (#93)\nVerkäufer:\nRüstmeister Huseng\nZone:\nEbenen von Ohn'ahra\nKosten:\n400\n\nLebhafter Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)Schmuck\nErhöht Eure Tempowertung um + 342.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 10 Sek. um 573 zu erhöhen und die Abklingzeit Eurer Gefechtstränke um 10 Sek. zu verringern.\n60\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
