entries[370707] = { ["name"] = "Transmutieren: Erwecktes Feuer", ["text"] = "Wirken in 3 sek. 1 tag Wiederaufladung\n7 Aufladungen\nReagenzien:\nErweckte Erde , Erweckte Luft\nBeute von:\nFeurige Weltkreaturen\nRezept:\nErhältlich im Auktionshaus\n\nErwecktes Feuer\nBenutzen: Verwandelt erwecktes Feuer in zehn Einheiten tobendes Feuer.\nHandwerksmaterial\n\"Erhältlich durch Sammelberufe und von verschiedenen elementaren Quellen auf den Dracheninseln. Kann im Auktionshaus verkauft und erworben werden.\"" }
entries[370708] = { ["name"] = "Transmutieren: Erweckter Frost", ["text"] = "Wirken in 3 sek. 1 tag Wiederaufladung\n7 Aufladungen\nReagenzien:\nErweckte Erde , Erweckte Luft\nVerkäufer:\nSteiz\nZone:\nAzurblaues Gebirge\nKobaltkonvent - Mittel\nKosten:\n50\n\nErweckter Frost\nBenutzen: Verwandelt erweckten Frost in zehn Einheiten tobenden Frost.\nHandwerksmaterial\n\"Erhältlich durch Sammelberufe und von verschiedenen elementaren Quellen auf den Dracheninseln. Kann im Auktionshaus verkauft und erworben werden.\"" }
entries[370710] = { ["name"] = "Transmutieren: Erweckte Erde", ["text"] = "Wirken in 3 sek. 1 tag Wiederaufladung\n7 Aufladungen\nReagenzien:\nErweckter Frost , Erwecktes Feuer\nBeute von:\nIrdene Weltkreaturen\nRezept:\nErhältlich im Auktionshaus\n\nErweckte Erde\nBenutzen: Verwandelt erweckte Erde in zehn Einheiten tobende Erde.\nHandwerksmaterial\n\"Erhältlich durch Sammelberufe und von verschiedenen elementaren Quellen auf den Dracheninseln. Kann im Auktionshaus verkauft und erworben werden.\"" }
entries[370711] = { ["name"] = "Transmutieren: Erweckte Luft", ["text"] = "Wirken in 3 sek. 1 tag Wiederaufladung\n7 Aufladungen\nReagenzien:\nErweckter Frost , Erwecktes Feuer\nBerufsausbilder:\nAlchemie der Dracheninseln (15)\nKosten:\n50\n\nErweckte Luft\nBenutzen: Verwandelt erweckte Luft in zehn Einheiten tobende Luft.\nHandwerksmaterial\n\"Erhältlich durch Sammelberufe und von verschiedenen elementaren Quellen auf den Dracheninseln. Kann im Auktionshaus verkauft und erworben werden.\"" }
